Scheme kc__4 := Elimination for Corelib.Init.Logic.or Sort Prop.
  Lemma Z_freech : forall c0 cp a, 0 <= c0 < kNumClasses -> In cp (rg_free_array (get_region st c0)) \/ In cp (pc_chunks (get_pc st c0)) ->
